CREATE TABLE IF NOT EXISTS content_items (
  id text PRIMARY KEY,
  content_type text NOT NULL CHECK (content_type IN ('package', 'blog', 'visa')),
  data jsonb NOT NULL,
  active boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS content_items_type_active_idx ON content_items(content_type, active);

ON CONFLICT (id) DO NOTHING;
